1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export interface QuoteResult {
36	  premium: number;
37	}
38	
39	export interface ClaimResult {
40	  payout: number;
41	  remainingCap: number;
42	}
43	
44	export type StepResult = QuoteResult | ClaimResult;
45	
46	export interface ScenarioResult {
47	  results: StepResult[];
48	}
49	
50	const PROCESSING_FEE = 5;
51	
52	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
53	
54	const BASE_PREMIUMS: Record<string, number> = {
55	  sword: 100,
56	  amulet: 60,
57	  staff: 80,
58	  potion: 40,
59	  rune: 25,
60	  moonstone: 25,
61	};
62	
63	const BLOCK_SIZE = 3;
64	
65	const BLOCK_BASE_PREMIUM = 60;
66	
67	// Every figure in a policy is a sum over some collection, so the fold itself
68	// is named once and the call sites say only what each element contributes.
69	const sumOf = <T>(items: T[], valueOf: (item: T) => number): number =>
70	  items.reduce((sum, item) => sum + valueOf(item), 0);
71	
72	const countByType = (items: Item[]): Map<string, number> => {
73	  const counts = new Map<string, number>();
74	
75	  for (const item of items) {
76	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
77	  }
78	
79	  return counts;
80	};
81	
82	const typeGroupBasePremiumOf = ([type, count]: [string, number]): number =>
83	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
84	
85	const policyBasePremiumOf = (items: Item[]): number =>
86	  sumOf([...countByType(items)], typeGroupBasePremiumOf);
87	
88	const HIGH_ENCHANTMENT_THRESHOLD = 5;
89	
90	// An item surcharge hits every item the predicate accepts, charging its rate
91	// against that item's own base premium.
92	interface ItemSurcharge {
93	  appliesTo: (item: Item) => boolean;
94	  rate: number;
95	}
96	
97	const ITEM_SURCHARGES: ItemSurcharge[] = [
98	  { appliesTo: (item) => item.cursed === true, rate: 0.5 },
99	  {
100	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
101	    rate: 0.3,
102	  },
103	];
104	
105	// One surcharge, totalled across every item it accepts.
106	const surchargeAcrossItems = (
107	  items: Item[],
108	  { appliesTo, rate }: ItemSurcharge,
109	): number =>
110	  sumOf(items.filter(appliesTo), (item) => BASE_PREMIUMS[item.type] * rate);
111	
112	// Item-specific surcharges apply to the affected item's own base premium.
113	const itemSurchargesOf = (items: Item[]): number =>
114	  sumOf(ITEM_SURCHARGES, (surcharge) => surchargeAcrossItems(items, surcharge));
115	
116	const LOYALTY_DISCOUNT_RATE = -0.2;
117	
118	const LOYALTY_YEARS_THRESHOLD = 2;
119	
120	const FOLLOW_UP_DISCOUNT_RATE = -0.15;
121	
122	// The context a policy-wide modifier is judged against: who the customer is,
123	// and how many quotes they have already been given in this scenario.
124	interface PolicyContext {
125	  customer: Customer;
126	  precedingQuotes: number;
127	}
128	
129	// A policy modifier hits the whole policy when the predicate accepts it,
130	// charging its rate against the policy base premium. Discounts are negative
131	// rates, so surcharges and discounts sum uniformly.
132	interface PolicyModifier {
133	  appliesTo: (context: PolicyContext) => boolean;
134	  rate: number;
135	}
136	
137	const POLICY_MODIFIERS: PolicyModifier[] = [
138	  { appliesTo: () => true, rate: FIRST_INSURANCE_SURCHARGE_RATE },
139	  {
140	    appliesTo: ({ customer }) =>
141	      customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
142	    rate: LOYALTY_DISCOUNT_RATE,
143	  },
144	  {
145	    appliesTo: ({ precedingQuotes }) => precedingQuotes >= 1,
146	    rate: FOLLOW_UP_DISCOUNT_RATE,
147	  },
148	];
149	
150	// Policy-wide modifiers apply to the policy base premium, so they are computed
151	// from the base alone — item-specific modifiers are not part of their base.
152	const policyModifiersOf = (policyBase: number, context: PolicyContext): number =>
153	  sumOf(
154	    POLICY_MODIFIERS.filter(({ appliesTo }) => appliesTo(context)),
155	    ({ rate }) => policyBase * rate,
156	  );
157	
158	const isInsurable = (item: Item): boolean => item.type in BASE_PREMIUMS;
159	
160	// MHPCO only writes policies over item types it has a price for, so an
161	// unpriceable item is rejected before any of it is quoted.
162	const rejectUninsurableItems = (items: Item[]): void => {
163	  const uninsurableItem = items.find((item) => !isInsurable(item));
164	
165	  if (uninsurableItem)
166	    throw new Error(`unknown item type: ${uninsurableItem.type}`);
167	};
168	
169	const quote = ({ items }: QuoteStep, context: PolicyContext): QuoteResult => {
170	  rejectUninsurableItems(items);
171	
172	  const policyBase = policyBasePremiumOf(items);
173	
174	  const premiumBeforeRounding =
175	    policyBase +
176	    itemSurchargesOf(items) +
177	    policyModifiersOf(policyBase, context) +
178	    PROCESSING_FEE;
179	
180	  return { premium: Math.ceil(premiumBeforeRounding) };
181	};
182	
183	const INSURANCE_VALUES: Record<string, number> = {
184	  sword: 1000,
185	  amulet: 600,
186	  staff: 800,
187	  potion: 400,
188	  rune: 250,
189	  moonstone: 250,
190	};
191	
192	const DEDUCTIBLE = 100;
193	
194	const CAP_MULTIPLE = 2;
195	
196	// A policy created by a quote step: what it covers, and how much of its
197	// payout cap is still available.
198	interface Policy {
199	  items: Item[];
200	  remainingCap: number;
201	}
202	
203	const policyFor = (items: Item[]): Policy => {
204	  const insuranceSum = sumOf(items, (item) => INSURANCE_VALUES[item.type]);
205	
206	  return { items, remainingCap: CAP_MULTIPLE * insuranceSum };
207	};
208	
209	const HALVED_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
210	
211	const HALF_REIMBURSEMENT_RATE = 0.5;
212	
213	const FULL_REIMBURSEMENT_RATE = 1;
214	
215	// Damage to a highly enchanted item is reimbursed at half, before the
216	// deductible is taken off.
217	const reimbursementRateFor = (item: Item): number =>
218	  (item.enchantment ?? 0) >= HALVED_REIMBURSEMENT_ENCHANTMENT_THRESHOLD
219	    ? HALF_REIMBURSEMENT_RATE
220	    : FULL_REIMBURSEMENT_RATE;
221	
222	const payoutForDamage = (damage: Damage, damagedItem: Item): number =>
223	  damage.amount * reimbursementRateFor(damagedItem) - DEDUCTIBLE;
224	
225	// Settling a claim both reports a result and draws down the policy's cap.
226	interface Settlement {
227	  result: ClaimResult;
228	  updatedPolicy: Policy;
229	}
230	
231	// A damage matched to the insured item it settles against.
232	interface MatchedDamage {
233	  damage: Damage;
234	  damagedItem: Item;
235	}
236	
237	// A claim only pays against items the policy actually covers, so a damage with
238	// no still-available item of its type is rejected before any of it is settled.
239	// Removes the matched item from `available`, so it cannot be matched twice.
240	const takeInsuredItemFor = (damage: Damage, available: Item[]): Item => {
241	  const index = available.findIndex((item) => item.type === damage.itemType);
242	
243	  if (index < 0)
244	    throw new Error(`damaged item is not insured: ${damage.itemType}`);
245	
246	  return available.splice(index, 1)[0];
247	};
248	
249	// Each damage settles against a distinct insured item, so a policy covering
250	// two swords can absorb two sword damages — one per insured sword. Matching an
251	// item consumes it, leaving it unavailable to later damages.
252	const matchDamagesToItems = (
253	  damages: Damage[],
254	  items: Item[],
255	): MatchedDamage[] => {
256	  const available = [...items];
257	
258	  return damages.map((damage) => ({
259	    damage,
260	    damagedItem: takeInsuredItemFor(damage, available),
261	  }));
262	};
263	
264	// MHPCO does not entertain damage reports it would have to pay backwards.
265	const rejectNegativeDamages = (damages: Damage[]): void => {
266	  const negative = damages.find((damage) => damage.amount < 0);
267	
268	  if (negative) throw new Error(`damage amount is negative: ${negative.amount}`);
269	};
270	
271	// The total payout per policy is capped, so a claim pays at most what the
272	// policy has left. Rounded down in the MHPCO's favour, so the cap is drawn
273	// down by whole G and both reported figures stay integers.
274	const payableUpTo = (remainingCap: number, desiredPayout: number): number =>
275	  Math.floor(Math.min(desiredPayout, remainingCap));
276	
277	const claim = ({ incident }: ClaimStep, policy: Policy): Settlement => {
278	  rejectNegativeDamages(incident.damages);
279	
280	  const desiredPayout = sumOf(
281	    matchDamagesToItems(incident.damages, policy.items),
282	    ({ damage, damagedItem }) => payoutForDamage(damage, damagedItem),
283	  );
284	
285	  const payout = payableUpTo(policy.remainingCap, desiredPayout);
286	
287	  const remainingCap = policy.remainingCap - payout;
288	
289	  return {
290	    result: { payout, remainingCap },
291	    updatedPolicy: { ...policy, remainingCap },
292	  };
293	};
294	
295	export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => {
296	  const results: StepResult[] = [];
297	
298	  const policies = new Map<number, Policy>();
299	
300	  let precedingQuotes = 0;
301	
302	  steps.forEach((step, index) => {
303	    if (step.op === "quote") {
304	      results.push(quote(step, { customer, precedingQuotes }));
305	      policies.set(index, policyFor(step.items));
306	      precedingQuotes += 1;
307	
308	      return;
309	    }
310	
311	    const { result, updatedPolicy } = claim(step, policies.get(step.policy)!);
312	
313	    results.push(result);
314	    policies.set(step.policy, updatedPolicy);
315	  });
316	
317	  return { results };
318	};
