3	const readStdin = async (): Promise<string> => {
4	  let input = "";
5	
6	  process.stdin.setEncoding("utf8");
7	
8	  for await (const chunk of process.stdin) input += chunk;
9	
10	  return input;
11	};
12	
13	// The CLI is a text-in/text-out shell around the engine: a scenario document
14	// arrives as JSON on stdin and its results leave as JSON on stdout.
15	const settle = (scenarioDocument: string): string =>
16	  JSON.stringify(runScenario(JSON.parse(scenarioDocument) as Scenario));
17	
18	// A rejected scenario is reported as a plain message, not a crash: nothing
19	// reaches stdout and the exit status marks the refusal.
20	try {
21	  process.stdout.write(settle(await readStdin()));
22	} catch (error) {
23	  process.stderr.write(`${(error as Error).message}\n`);
24	  process.exitCode = 1;
25	}
